public class EntityManager<T> {
    private Map<Class<?>, EntityFactory<T>> factories = new HashMap<>();

    public <E extends T> void registerFactory(Class<E> type, EntityFactory<E> factory) {
        factories.put(type, (EntityFactory<T>) factory);
    }

    public <E extends T> E createEntity(Class<E> type) {
        return (E) factories.get(type).create();
    }
}
